/* @lc app=leetcode id=3977 lang=kotlin */ class Solution { fun minTimeMaxPower(n: Int, edges: Array<IntArray>, power: Int, cost: IntArray, source: Int, target: Int): LongArray = edges.groupBy { it[0] }.let { adj -> LongArray(n * (power + 1)) { Long.MAX_VALUE }.let { dist -> java.util.PriorityQueue<LongArray>(compareBy<LongArray> { it[0] }).let { pq -> dist.set(source * (power + 1) + power, 0L).also { pq.add(longArrayOf(0L, (source * (power + 1) + power).toLong())) }.let { generateSequence { pq.poll() }.forEach { (d, s) -> if (d == dist[s.toInt()]) (s.toInt() / (power + 1)).also { u -> (s.toInt() % (power + 1)).also { p -> if (p >= cost[u]) adj[u].orEmpty().forEach { e -> (e[1] * (power + 1) + p - cost[u]).also { ns -> if (d + e[2] < dist[ns]) dist.set(ns, d + e[2]).also { pq.add(longArrayOf(d + e[2], ns.toLong())) } } } } } } }.let { (0..power).filter { dist[target * (power + 1) + it] != Long.MAX_VALUE }.let { ok -> if (ok.isEmpty()) longArrayOf(-1, -1) else ok.minOf { dist[target * (power + 1) + it] }.let { t -> longArrayOf(t, ok.filter { dist[target * (power + 1) + it] == t }.max().toLong()) } } } } } } }